\title{Unconditional Cycle Obstructions for the Collatz Step Map}
\author{Aristotle}
\date{2026-06-27}

\begin{document}
\maketitle

\begin{abstract}
The Collatz Conjecture asserts that the iterated dynamics of the map $T(n) = n/2$
for even $n$ and $T(n) = 3n+1$ for odd $n$ drives every positive integer to $1$.
While the global conjecture remains open, a great deal can be established
\emph{unconditionally} about the local and cyclic structure of $T$. We give a
self-contained, fully formalized development of a logically complete chain of
obstructions to the existence of nontrivial periodic orbits. We establish: (i) the
parity evaluation rules; (ii) the one-step monotonicity dichotomy --- even steps
strictly decrease positive inputs (\texttt{T\_lt\_of\_even}) while odd steps strictly
increase any input (\texttt{T\_gt\_of\_odd}); (iii) the absence of positive fixed points
(\texttt{T\_no\_fixed\_point}); (iv) an exact ``all-even descent'' identity stating that a
run of $k$ consecutive even iterates divides the input by $2^k$
(\texttt{all\_even\_descent}); and (v) the structural theorem that every positive periodic
orbit must contain an odd element (\texttt{periodic\_has\_odd}). The last result rules out the
simplest conceivable counterexample to Collatz --- a cycle composed entirely of halving
steps --- and exposes the precise mechanism by which any putative nontrivial cycle is
forced to repeatedly invoke the expanding odd rule. We discuss the placement of these
results within the theory of stopping times, ergodic averages, and $2$-adic dynamics, and
we outline a research program extending each obstruction.
\end{abstract}

\section{Introduction}

\subsection{The problem}
Define the \textbf{Collatz step map} $T : \mathbb{N} \to \mathbb{N}$ by
\[
T(n) = \begin{cases} n/2 & \text{if } n \equiv 0 \pmod 2, \\ 3n + 1 & \text{if } n \equiv 1 \pmod 2, \end{cases}
\]
where $n/2$ is the exact integer quotient when $n$ is even. Write $T^{[k]}$ for the
$k$-fold iterate, with $T^{[0]} = \mathrm{id}$.

\begin{conjecture}[Collatz, c.\ 1937]
For every positive integer $n$ there exists $k \ge 0$ with $T^{[k]}(n) = 1$.
\end{conjecture}

The conjecture has been verified computationally for all $n \le 2^{68} \approx 2.95
\times 10^{20}$, yet a proof has eluded mathematics for over eight decades.

\subsection{The two failure modes}
A counterexample must exhibit either \emph{divergence} (an unbounded orbit) or
\emph{nontrivial cycling} (a periodic loop disjoint from the trivial cycle
$\{1,4,2\}$). This paper develops \emph{unconditional obstructions to cycling}: every
result holds for all positive integers without assuming the conjecture.

\subsection{Methodology and scope}
All results were formalized and mechanically verified in the Lean~4 theorem prover with
the Mathlib library, as the modules \texttt{Applications.Collatz.Basic} and
\texttt{Applications.Collatz.CycleObstruction}. The proofs below are faithful prose
renderings. These are \emph{partial results}: none resolves the conjecture. Their value
is in establishing, with certainty, structural constraints that any counterexample must
satisfy.

\section{Definitions and elementary lemmas}

Throughout, $\mathbb{N} = \{0,1,2,\dots\}$ and all division is integer (floor) division;
for even $n$ the quotient $n/2$ is exact.

\begin{definition}[Collatz step map]
\[
T(n) = \begin{cases} n/2 & \text{if } n \bmod 2 = 0, \\ 3n + 1 & \text{otherwise.} \end{cases}
\]
\end{definition}

\begin{lemma}[\texttt{T\_even}]
If $n$ is even, then $T(n) = n/2$.
\end{lemma}
\begin{proof}
The defining branch tests $n \bmod 2 = 0$, true for even $n$, selecting the value $n/2$.
\end{proof}

\begin{lemma}[\texttt{T\_odd}]
If $n$ is odd, then $T(n) = 3n + 1$.
\end{lemma}
\begin{proof}
For odd $n$, $n \bmod 2 = 1 \ne 0$, so $T(n)$ takes the else branch, $3n+1$.
\end{proof}

\begin{lemma}[\texttt{T\_lt\_of\_even}; even steps strictly descend]
If $n > 0$ and $n$ is even, then $T(n) < n$.
\end{lemma}
\begin{proof}
$T(n) = n/2$ by the previous lemma, and for $n>0$ with divisor $2>1$ integer division
gives $n/2 < n$.
\end{proof}

\begin{lemma}[\texttt{T\_gt\_of\_odd}; odd steps strictly ascend]
If $n$ is odd, then $T(n) > n$.
\end{lemma}
\begin{proof}
$T(n) = 3n+1 > n$ since $3n+1-n = 2n+1 \ge 1 > 0$.
\end{proof}

\noindent Lemmas 2.3 and 2.4 form the \textbf{monotonicity dichotomy}: every even step
strictly shrinks a positive number, every odd step strictly grows it. This dichotomy
drives all cyclic obstructions below.

\section{Unconditional cycle obstructions}

\subsection{No fixed points}
\begin{theorem}[\texttt{T\_no\_fixed\_point}]
For every $n > 0$, $T(n) \ne n$.
\end{theorem}
\begin{proof}
If $n$ is even, $T(n) < n$; if $n$ is odd, $T(n) > n$. Either way $T(n) \ne n$.
\end{proof}

\subsection{The all-even descent identity}
\begin{theorem}[\texttt{all\_even\_descent}]
Let $n,k \in \mathbb{N}$. If $T^{[i]}(n)$ is even for every $i$ with $0 \le i < k$, then
\[
T^{[k]}(n) = \frac{n}{2^k}.
\]
\end{theorem}
\begin{proof}
Induction on $k$. For $k=0$, $T^{[0]}(n) = n = n/2^0$. For the step, assume the result for
$k$. The hypothesis for indices $<k$ gives $T^{[k]}(n) = n/2^k$, and the hypothesis at
$i=k$ says $T^{[k]}(n)$ is even, so
\[
T^{[k+1]}(n) = T\big(T^{[k]}(n)\big) = \frac{T^{[k]}(n)}{2}
= \frac{n/2^k}{2} = \frac{n}{2^{k+1}},
\]
using $(n/a)/b = n/(ab)$ and $2^k\cdot 2 = 2^{k+1}$.
\end{proof}

\begin{remark}
The identity is exact in integer arithmetic precisely because the evenness hypothesis
makes each halving exact, so the conclusion is an equality, not merely an inequality.
\end{remark}

\subsection{Every cycle contains an odd element}
A \emph{periodic point} of period $p \ge 1$ is a positive integer $n$ with $T^{[p]}(n) = n$.

\begin{theorem}[\texttt{periodic\_has\_odd}]
Let $n > 0$ and $p > 0$ satisfy $T^{[p]}(n) = n$. Then there exists $i$ with $0 \le i < p$
such that $T^{[i]}(n)$ is odd.
\end{theorem}
\begin{proof}
Suppose not: $T^{[i]}(n)$ is even for all $i < p$. Then by the descent identity with $k=p$,
$T^{[p]}(n) = n/2^p$. By periodicity $T^{[p]}(n) = n$, so $n = n/2^p$. But $p \ge 1$ gives
$2^p \ge 2$, whence $n/2^p < n$ for $n > 0$, so $n = n/2^p < n$, a contradiction. Hence some
$T^{[i]}(n)$ with $i<p$ is odd.
\end{proof}

\begin{remark}
Any nontrivial cycle must invoke the expanding odd rule $n \mapsto 3n+1$ at least once;
pure halving strictly shrinks and cannot close a loop. This is the discrete seed of the
heuristic that a cycle with $O$ odd and $E$ even steps obeys $3^{O} \approx 2^{E}$, i.e.\
$E/O \approx \log 3/\log 2$.
\end{remark}

\section{Algorithms}

\subsection{Orbit iteration and trajectory profiling}
Given $n>0$, iterate $T$ until reaching $1$ (or a budget), recording the stopping time, the
maximum value attained, and the parity word (the E/O step sequence). Each step costs $O(b)$
bit operations for $b$-bit numbers. A run of $k$ even steps multiplies the value by $2^{-k}$
(Theorem 3.2), and a full period cannot be all-E (Theorem 3.3).

\begin{verbatim}
function COLLATZ_TRAJECTORY(n, max_steps):
    trajectory <- [n]; parity_word <- ""; steps <- 0
    while n != 1 and steps < max_steps:
        if n mod 2 == 0: parity_word += "E"; n <- n/2
        else:            parity_word += "O"; n <- 3*n+1
        append n to trajectory; steps += 1
    return (trajectory, parity_word, steps, max(trajectory))
\end{verbatim}

\subsection{Cycle detection via Floyd's algorithm}
Floyd's tortoise-and-hare detects a cycle in $O(\lambda+\mu)$ map evaluations and $O(1)$
memory, then locates an odd witness in the cycle, empirically confirming Theorem 3.3.

\begin{verbatim}
function FIND_CYCLE(n):
    slow <- T(n); fast <- T(T(n))
    while slow != fast: slow <- T(slow); fast <- T(T(fast))
    mu <- 0; slow <- n
    while slow != fast: slow <- T(slow); fast <- T(fast); mu += 1
    cycle <- [slow]; x <- T(slow); odd_witness <- none
    while x != slow:
        if x is odd and odd_witness is none: odd_witness <- x
        append x to cycle; x <- T(x)
    return (cycle, odd_witness)
\end{verbatim}

\section{Applications and connections}

\subsection{Stopping times}
The stopping time $\sigma(n)$ is the least $k>0$ with $T^{[k]}(n) < n$. The monotonicity
dichotomy is the atomic ingredient of every stopping-time estimate; residue-class analysis
(e.g.\ $n \equiv 1 \pmod 4$) certifies positive-density tame sets unconditionally, with
Theorem 3.2 as the exact computation for even prefixes.

\subsection{Ergodic theory}
Treating $T$ as a measure-preserving transformation enables Birkhoff averages and mixing
arguments. The geometric-mean multiplier $\sqrt{3}/2 < 1$ predicts typical descent; Tao's
theorem that orbits attain almost bounded values almost everywhere is the deepest such
result.

\subsection{$2$-adic dynamics}
The number of available halvings at $n$ is its $2$-adic valuation $v_2(n)$, and Theorem 3.2
states $T^{[k]}(n) = n/2^k$ whenever $k \le v_2(n)$. The accelerated odd map lifts to a
measure-preserving homeomorphism of $\mathbb{Z}_2$ conjugate to the shift, recasting
convergence as transitivity of the shift orbit of $1$.

\section{Discussion}
The architecture is economical: parity-evaluation lemmas yield the monotonicity dichotomy,
which yields both the no-fixed-point result and, via the descent identity, the central cycle
theorem. Every link is mechanically verified. The results close the all-even cycle escape
route completely and quantify the odd/even tension, but do not bound cycle lengths, rule out
divergence, or prove convergence beyond residue certificates: the conjecture remains open.

\section{Future work}
\begin{enumerate}
\item \textbf{Uniform stopping-time bounds mod $2^m$:} all but $n \equiv 1 \pmod{2^m}$ drop
below $n$ within $2m$ steps, via affine maps $n \mapsto (3^a n + c)/2^m$.
\item \textbf{Cycle-length lower bound:} any nontrivial cycle of length $k$ has at least
$k\,\log 2/\log 3$ odd elements, sharpening Theorem 3.3.
\item \textbf{$2$-adic conjugacy} of the accelerated odd map to the shift on $\mathbb{Z}_2$.
\item \textbf{Density of the unconditionally-convergent set} equals $1$ via iterated residue
certificates, even as full convergence stays open.
\end{enumerate}

